using System;
using System.Drawing;
using System.Collections.Generic;
using WoWProbe;
class CampaignSessionTests
{
    sealed class Fake:ICampaignInputBackend
    {public bool Focus=true,Emergency,Held,MouseHeld,FailDown,FailUp;public int Downs,Ups,MouseDowns,MouseUps;public Point Position;public Rectangle Bounds=new Rectangle(20,30,1920,1080);public Action BeforeMove,BeforeKeyCheck,BeforeBounds,AfterMouseDown;public Action<ushort> AfterKey;public List<string> Events=new List<string>();public Rectangle ClientBounds(){if(BeforeBounds!=null)BeforeBounds();return Bounds;}public bool IsTargetForeground(){return Focus;}public bool IsEmergencyPressed(){return Emergency;}public bool IsKeyAlreadyDown(ushort k){if(BeforeKeyCheck!=null)BeforeKeyCheck();return Held;}public void KeyDown(ushort k){Downs++;Events.Add("KD"+k);if(AfterKey!=null)AfterKey(k);if(FailDown)throw new Exception("down");}public void KeyUp(ushort k){Ups++;Events.Add("KU"+k);if(FailUp)throw new Exception("up");}public bool IsMouseAlreadyDown(bool r){return MouseHeld;}public void MoveMouse(Point p){Position=p;if(BeforeMove!=null)BeforeMove();}public void MouseDown(bool r){MouseDowns++;Events.Add(r?"MRD":"MLD");if(AfterMouseDown!=null)AfterMouseDown();if(FailDown)throw new Exception("mouse down");}public void MouseUp(bool r){MouseUps++;Events.Add(r?"MRU":"MLU");if(FailUp)throw new Exception("mouse up");}}
    sealed class Env
    {public long Time;public OperationObservation O=CampaignFixtures.Sample();public CampaignPlan P=CampaignFixtures.Plan();public Fake B=new Fake();public InputFailureLatch Latch=new InputFailureLatch();public CampaignSession S;public Action<string> Logger;public Action OnRead,OnClock;public Func<Rectangle,bool> RegionAllowed;
        public Env(bool dead){P.Settings.BindingsConfirmed=P.Settings.UiConfirmed=P.Settings.AutoResumeConfirmed=P.Battle.BindingsConfirmed=P.Battle.Calibration.Confirmed=P.Battle.ApproachPositionConfirmed=true;if(dead){O.Farm.PlayerDead=true;O.Farm.Health=0;O.ReleaseVisible=O.ReleaseEnabled=true;}}
        public void Start(){S=new CampaignSession(B,delegate{if(OnClock!=null)OnClock();return Time;},delegate{if(OnRead!=null)OnRead();return O;},delegate(string s){if(Logger!=null)Logger(s);},Latch,RegionAllowed);S.Start(P);}
        public void Pump(){for(int i=0;i<15&&S.IsActive&&!S.IsHolding;i++){Time=5000+i*100;CampaignFixtures.Next(O);S.Tick();}}
    }
    static int pass,fail;static void Assert(bool b){if(!b)throw new Exception("assertion failed");}static void Test(string n,Action a){try{a();pass++;Console.WriteLine("PASS "+n);}catch(Exception e){fail++;Console.WriteLine("FAIL "+n+": "+e.Message);}}
    static void Reject(Action a){try{a();}catch(InvalidOperationException){return;}throw new Exception("unsafe session armed");}
    static Env Vendor()
    {
        var e=new Env(false);e.O.FreeSlots=0;e.O.Farm.BagFull=true;
        e.P.VendorRoute.Points=new List<Waypoint>{new Waypoint{X=.5,Y=.5},new Waypoint{X=.5001,Y=.5}};
        e.B.AfterKey=delegate(ushort k){
            if(k==e.P.Settings.NpcSelectKey){e.O.Farm.TargetExists=e.O.Farm.TargetIdentityKnown=e.O.Farm.NameHashKnown=e.O.Farm.AttackabilityKnown=e.O.Farm.TargetDeadKnown=true;e.O.Farm.TargetToken=77;e.O.Farm.TargetHealth=100;foreach(var t in e.P.Battle.Targets)if(t.Kind=="npc")e.O.Farm.TargetNameHash=t.NameHash;}
            else if(k==0x46){e.O.MerchantOpen=true;e.O.MerchantOpened++;e.O.MerchantTargetToken=e.O.Farm.TargetToken;e.O.MerchantNameHash=e.O.Farm.TargetNameHash;}
            else if(k==0x42){e.O.InventoryKnown=e.O.InventoryEventsKnown=e.O.InventoryCycleKnown=true;e.O.InventoryRevision=10;e.O.TotalSlots=2;e.O.PageIndex=0;e.O.BagSizes=new byte[]{2,0,0,0,0};e.O.Occupancy=new byte[25];e.O.Occupancy[0]=3;e.O.Item=new InventoryItem{Bag=0,Slot=1,Count=1,Quality=0,ItemId=1001,Fingerprint=500,UnitPrice=5,Known=true,QuestKnown=true,TypeKnown=true,RectangleKnown=true,Region=new Rectangle(1300,600,35,35)};}
            else if(k==0x1B&&e.O.MerchantOpen){e.O.MerchantOpen=false;e.O.MerchantClosed++;}
        };return e;
    }
    static void ThroughSale(Env e)
    {for(int i=0;i<100&&e.S.IsActive&&e.B.MouseDowns==0;i++){e.Time=5000+i*300;CampaignFixtures.Next(e.O);e.S.Tick();}if(e.B.MouseDowns==0&&e.S.IsActive)throw new Exception("vendor did not reach its actual right-click command: "+e.S.EngineStatus);}
    static bool Selling(Env e){return e.S!=null&&e.S.LastCommand!=null&&e.S.LastCommand.Purpose==OperationPurpose.Sell;}
    static int Main()
    {
        Test("full live confirmations are required",delegate{var e=new Env(false);e.P.Settings.UiConfirmed=false;Reject(e.Start);Assert(e.B.Downs+e.B.MouseDowns==0);});
        Test("five second countdown sends no keyboard or mouse",delegate{var e=new Env(true);e.Start();e.Time=4999;e.S.Tick();Assert(e.B.Downs+e.B.MouseDowns==0);e.S.Stop("done");});
        Test("release click uses known client region and paired mouse up",delegate{var e=new Env(true);e.Start();e.Pump();Assert(e.S.IsHolding&&e.B.MouseDowns==1&&e.B.Position==new Point(795,500));e.Time+=250;e.S.Tick();Assert(!e.S.IsHolding&&e.B.MouseUps==1);e.S.Stop("done");Assert(e.B.MouseUps==1);});
        Test("F12 and focus loss cancel owned mouse input",delegate{foreach(bool emergency in new[]{false,true}){var e=new Env(true);e.Start();e.Pump();if(emergency)e.B.Emergency=true;else e.B.Focus=false;e.Time++;e.S.Tick();Assert(!e.S.IsActive&&e.B.MouseUps==1);}});
        Test("stale sequence stream and layout changes release and stop",delegate{foreach(bool layout in new[]{false,true}){var e=new Env(true);e.Start();e.Pump();if(layout)e.O.LayoutToken++;else e.O.Fresh=false;e.Time++;e.S.Tick();Assert(!e.S.IsActive&&e.B.MouseUps==1);}});
        Test("mouse move callback cannot invalidate button before down",delegate{var e=new Env(true);e.B.BeforeMove=delegate{e.O.ReleaseVisible=false;};e.Start();e.Pump();Assert(!e.S.IsActive&&e.B.MouseDowns==0&&e.B.MouseUps==0);});
        Test("user held mouse button is never borrowed or released",delegate{var e=new Env(true);e.B.MouseHeld=true;e.Start();e.Pump();Assert(e.B.MouseDowns==0&&e.B.MouseUps==0&&!e.S.IsActive);});
        Test("partial mouse down failure releases once and latches all modes",delegate{var e=new Env(true);e.B.FailDown=true;e.Start();e.Pump();Assert(e.Latch.Faulted&&!e.S.IsActive&&e.B.MouseUps==1);e.B.FailDown=false;Reject(e.Start);});
        Test("failed mouse up latches without endlessly sending releases",delegate{var e=new Env(true);e.Start();e.Pump();e.B.FailUp=true;e.S.Stop("stop");e.S.Tick();Assert(e.Latch.Faulted&&e.B.MouseUps==1);});
        Test("logging cancellation and recursive ticks never send orphan mouse down",delegate{var e=new Env(true);e.Logger=delegate(string s){if(s.StartsWith("Campaign pulse")){e.S.Tick();e.S.Stop("callback");}};e.Start();e.Pump();Assert(!e.S.IsActive&&e.B.MouseDowns==0);});
        Test("preflight reader cancellation preserves stop",delegate{var e=new Env(false);bool once=true;e.OnRead=delegate{if(e.S!=null&&once){once=false;e.S.Stop("preflight");}};Reject(e.Start);Assert(e.B.Downs+e.B.MouseDowns==0);});
        Test("held release accepts actual ghost transition and releases early",delegate{var e=new Env(true);e.Start();e.Pump();e.O.Farm.PlayerDead=false;e.O.Farm.PlayerGhost=true;e.O.ReleaseVisible=e.O.ReleaseEnabled=false;e.Time++;e.S.Tick();Assert(e.S.IsActive&&!e.S.IsHolding&&e.B.MouseUps==1);e.S.Stop("done");});
        Test("unknown dialog during hold releases and stops",delegate{var e=new Env(true);e.Start();e.Pump();e.O.ReleaseKnown=false;e.Time++;e.S.Tick();Assert(!e.S.IsActive&&e.B.MouseUps==1);});
        Test("unsafe UI region overlapping telemetry is rejected",delegate{var e=new Env(true);e.O.ReleaseRegion=new Rectangle(20,20,100,30);e.Start();e.Pump();Assert(e.B.MouseDowns==0&&!e.S.IsActive);});
        Test("global latch changing during logging cannot arm new input",delegate{var e=new Env(true);e.Logger=delegate(string s){if(s.StartsWith("Campaign pulse"))e.Latch.Fail("other mode");};e.Start();e.Pump();Assert(e.B.MouseDowns==0&&!e.S.IsActive);});
        Test("cancel and rearm inside log cannot carry old action past new countdown",delegate{var e=new Env(true);bool once=true;e.Logger=delegate(string s){if(once&&s.StartsWith("Campaign pulse")){once=false;e.S.Stop("replace");e.S.Start(e.P);}};e.Start();e.Pump();Assert(e.B.MouseDowns==0&&e.S.IsActive);e.S.Stop("done");});
        Test("actual vendor engine reaches a guarded right click on its eligible slot",delegate{var e=Vendor();e.Start();ThroughSale(e);Assert(e.S.IsHolding&&e.B.MouseDowns==1&&e.B.Position==new Point(1337,647)&&Selling(e));e.S.Stop("done");Assert(e.B.MouseUps==1);});
        Test("right click rechecks merchant sale tab cursor modal item identity and revision after movement",delegate{
            Action<Env>[] changes={delegate(Env e){e.O.MerchantTargetToken++;},delegate(Env e){e.O.SellTab=false;},delegate(Env e){e.O.CursorEmpty=false;},delegate(Env e){e.O.ConfirmationVisible=true;},delegate(Env e){e.O.Item.ItemId++;},delegate(Env e){e.O.Item.Fingerprint++;},delegate(Env e){e.O.Item.Count++;},delegate(Env e){e.O.InventoryRevision++;},delegate(Env e){e.O.Item.Quest=true;},delegate(Env e){e.O.Item.Locked=true;},delegate(Env e){e.O.Item.Region=new Rectangle(1400,600,35,35);}};
            foreach(var change in changes){var e=Vendor();e.B.BeforeMove=delegate{change(e);};e.Start();ThroughSale(e);Assert(!e.S.IsActive&&e.B.MouseDowns==0&&e.B.MouseUps==0);}
        });
        Test("late region callback cannot mutate a sale candidate before right down",delegate{var e=Vendor();e.RegionAllowed=delegate(Rectangle r){e.O.Item.ItemId++;return true;};e.Start();ThroughSale(e);Assert(!e.S.IsActive&&e.B.MouseDowns==0&&e.B.MouseUps==0);});
        Test("moving the game window after cursor placement cancels the old screen point",delegate{var e=Vendor();e.B.BeforeMove=delegate{e.B.Bounds=new Rectangle(120,30,1920,1080);};e.Start();ThroughSale(e);Assert(!e.S.IsActive&&e.B.MouseDowns==0);});
        Test("a user mouse press during cursor movement is never borrowed",delegate{var e=Vendor();e.B.BeforeMove=delegate{e.B.MouseHeld=true;};e.Start();ThroughSale(e);Assert(!e.S.IsActive&&e.B.MouseDowns==0&&e.B.MouseUps==0);});
        Test("last clock callback rechecks destination focus and emergency before sale down",delegate{foreach(bool emergency in new[]{false,true}){var e=Vendor();e.OnClock=delegate{if(Selling(e)){if(emergency)e.B.Emergency=true;else e.B.Focus=false;}};e.Start();ThroughSale(e);Assert(!e.S.IsActive&&e.B.MouseDowns==0);}});
        Test("sale acknowledgement releases then requires a genuinely newer observation",delegate{var e=Vendor();e.Start();ThroughSale(e);int downs=e.B.Downs;e.O.InventoryRevision++;e.O.Occupancy[0]=2;e.O.FreeSlots=2;e.O.Farm.BagFull=false;e.O.Item.Empty=true;e.O.Item.ItemId=0;CampaignFixtures.Next(e.O);e.Time++;e.S.Tick();Assert(e.S.IsActive&&!e.S.IsHolding&&e.B.MouseUps==1);for(int i=0;i<4;i++){e.Time+=100;e.S.Tick();}Assert(e.B.Downs==downs&&e.B.MouseDowns==1);e.S.Stop("done");});
        Test("user held keyboard input is not borrowed and key failures share the latch",delegate{var held=new Env(false);held.B.Held=true;held.Start();held.Pump();Assert(!held.S.IsActive&&held.B.Downs==0&&held.B.Ups==0);var partial=new Env(false);partial.B.FailDown=true;partial.Start();partial.Pump();Assert(partial.Latch.Faulted&&partial.B.Downs==1&&partial.B.Ups==1);});
        Test("keyboard callback cancellation and last clock ownership change cannot press",delegate{var cancelled=new Env(false);cancelled.B.BeforeKeyCheck=delegate{cancelled.S.Stop("key callback");};cancelled.Start();cancelled.Pump();Assert(!cancelled.S.IsActive&&cancelled.B.Downs==0);var held=new Env(false);held.OnClock=delegate{if(held.S!=null&&held.S.LastCommand!=null&&held.S.LastCommand.Action==OperationAction.Key)held.B.Held=true;};held.Start();held.Pump();Assert(!held.S.IsActive&&held.B.Downs==0&&held.B.Ups==0);});
        Test("arming clock cancellation and bounds callback cancellation preserve Stop",delegate{var clock=new Env(false);clock.OnClock=delegate{if(clock.S!=null)clock.S.Stop("arming clock");};Reject(clock.Start);Assert(clock.B.Downs==0);var bounds=new Env(false);bounds.B.BeforeBounds=delegate{if(bounds.S!=null)bounds.S.Stop("arming bounds");};Reject(bounds.Start);Assert(bounds.B.Downs==0);});
        Test("death interrupts an owned farm key before recovery can click",delegate{var e=new Env(false);e.Start();e.Pump();Assert(e.S.IsHolding&&e.B.Downs==1);e.O.Farm.PlayerDead=true;e.O.Farm.Health=0;e.O.ReleaseVisible=e.O.ReleaseEnabled=true;CampaignFixtures.Next(e.O);e.Time++;e.S.Tick();Assert(!e.S.IsHolding&&e.B.Ups==1&&e.B.MouseDowns==0&&e.S.IsActive);for(int i=0;i<10&&e.B.MouseDowns==0&&e.S.IsActive;i++){CampaignFixtures.Next(e.O);e.Time+=100;e.S.Tick();}Assert(e.B.MouseDowns==1&&e.B.Events.IndexOf("KU"+e.B.Events[0].Substring(2))<e.B.Events.IndexOf("MLD"));e.S.Stop("done");});
        Test("partial sale mouse-down failure releases once even when inventory already acknowledged",delegate{var e=Vendor();e.B.BeforeMove=delegate{e.B.FailDown=true;};e.B.AfterMouseDown=delegate{e.O.InventoryRevision++;e.O.Occupancy[0]=2;e.O.FreeSlots=2;};e.Start();ThroughSale(e);Assert(!e.S.IsActive&&e.Latch.Faulted&&e.B.MouseDowns==1&&e.B.MouseUps==1);e.Time+=5000;e.S.Tick();Assert(e.B.MouseUps==1);});
        Test("sale deadline overflow cannot claim or release an unpressed button",delegate{var e=Vendor();e.OnClock=delegate{if(Selling(e))e.Time=Int64.MaxValue-20;};e.Start();ThroughSale(e);Assert(!e.S.IsActive&&e.Latch.Faulted&&e.B.MouseDowns==0&&e.B.MouseUps==0);});
        Console.WriteLine("Campaign session tests: "+pass+" passed, "+fail+" failed; fake backend only.");return fail==0?0:1;
    }
}
